<?= $this->extend('player/layouts/main') ?>
<?= $this->section('title') ?>Open Play<?= $this->endSection() ?>
<?= $this->section('content') ?>
<div class="container py-4"><div class="d-flex justify-content-between align-items-center mb-3"><div><h1 class="h3 mb-1">Open Play</h1><p class="text-muted mb-0">Tham gia session phù hợp trình độ và lịch của bạn.</p></div><a class="btn btn-primary" href="/player/open-play/create"><i class="bi bi-plus-circle"></i> Tạo session</a></div>
<?php if (!$sessions): ?><div class="alert alert-light border">Chưa có Open Play hôm nay.</div><?php endif; ?>
<div class="row g-3"><?php foreach ($sessions as $session): ?><div class="col-md-6"><div class="card h-100 shadow-sm"><div class="card-body"><div class="d-flex justify-content-between"><h2 class="h5 mb-1"><?= esc($session->title) ?></h2><span class="badge text-bg-<?= $session->status === 'full' ? 'warning' : 'success' ?>"><?= esc($session->status) ?></span></div><div class="small text-muted mb-3"><?= esc($session->session_date) ?> · <?= esc(substr($session->start_time, 0, 5) . ' - ' . substr($session->end_time, 0, 5)) ?> · <?= (int) $session->capacity ?> người</div><div class="mb-3"><?php foreach (($participants[(int) $session->id] ?? []) as $entry): ?><span class="badge text-bg-light me-1">Người chơi #<?= (int) $entry->player_id ?> · <?= esc($entry->status) ?></span><?php endforeach; ?></div><?php $entry = $entries[(int) $session->id] ?? null; ?><?php if ($entry && $entry->status !== 'cancelled'): ?><form method="post" action="/player/open-play/leave/<?= (int) $session->id ?>"><?= csrf_field() ?><button class="btn btn-outline-danger btn-sm">Rời session</button></form><?php else: ?><form method="post" action="/player/open-play/join/<?= (int) $session->id ?>"><?= csrf_field() ?><button class="btn btn-outline-primary btn-sm"><?= $session->status === 'full' ? 'Vào waitlist' : 'Tham gia' ?></button></form><?php endif; ?></div></div></div><?php endforeach; ?></div></div>
<?= $this->endSection() ?>
